INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18901, 'Jeremiah 44:4', 'Jeremiah', 44, 4, '&nbsp;ما بار بار تاسو ته خپل خِدمتګاران پېغمبران درولېږل، هغوئ تاسو ته مِنت وکړو چې دا حرامکارى مۀ کوئ د کوم نه چې زۀ نفرت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18902, 'Jeremiah 44:5', 'Jeremiah', 44, 5, '&nbsp;خو هغوئ د نبيانو خبرو ته غوږ ونۀ نيولو او نۀ يې توجو ورکړه، او هغوئ د خپلو هغه بد عملونو نه راونۀ ګرځېدل او نۀ يې غېر معبودانو ته خوشبو سوزول بند کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18903, 'Jeremiah 44:6', 'Jeremiah', 44, 6, '&nbsp;نو په دې وجه ما خپل سخت قهر د يهوداه په ښارونو او د يروشلم په کوڅو لکه د اور په شان نازل کړو، او هغه يې تر نن ورځ پورې تباه او په خرابه بدل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18904, 'Jeremiah 44:7', 'Jeremiah', 44, 7, '&nbsp;نو اوس مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ تاسو نه تپوس کوم چې، تاسو ولې خپل ځانونه تباه کوئ؟ په تاسو کښې به نۀ نارينه، نۀ زنانه، نۀ ماشومان او نۀ تې خوړونکى هيڅوک هم ژوندى پاتې نۀ شى څوک چې دلته د يهوداه نه راغلى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18905, 'Jeremiah 44:8', 'Jeremiah', 44, 8, '&nbsp;تاسو په مِصر کښې نورو معبودانو او بُتانو ته د خوشبويۍ نذرانې پېش کولو سره ما ولې غصه کوئ؟ تاسو به په دې کار کولو سره صرف خپل ځان تباه کړئ او د دُنيا د نورو خلقو د لعنت، خندا او مسخرو به وګرځوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18906, 'Jeremiah 44:9', 'Jeremiah', 44, 9, '&nbsp;ولې تاسو د خپل پلار نيکۀ ګناهونه، د يهوداه د بادشاهانو او د مَلِکو ګناهونه، او هغه ګناهونه چې تاسو او ستاسو ښځو په يهوداه او يروشلم کښې کړى دى هېر کړل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18907, 'Jeremiah 44:10', 'Jeremiah', 44, 10, '&nbsp;خو تر ننه پورې نۀ تاسو په خپل ځان کښې خاکسارى راوستې ده او نۀ مو په خپلو بدو کارونو پښېمانى ښکاره کړې ده. په تاسو کښې هيچا، نۀ زما د شريعت په مطابق او نۀ زما د اصُولو په مطابق ژوند کړے دے کوم چې ما ستاسو نه وړاندې ستاسو پلار نيکۀ ته ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18908, 'Jeremiah 44:11', 'Jeremiah', 44, 11, '&nbsp;نو په دې وجه، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ما په خپله دا کلکه اراده وکړه چې ټوله يهوداه تباه او هلاکه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18909, 'Jeremiah 44:12', 'Jeremiah', 44, 12, '&nbsp;زۀ به د يهوداه هغه ژوندى پاتې شوى خلق راواخلم هغه څوک چا چې په مِصر کښې په پناه اخستو او اوسېدو زور راوړے وو. زۀ به هغوئ تباه کړم. هغوئ ټول لوئ او واړۀ به په مِصر کښې په جنګ، قحط او وبا باندې مړۀ او تباه کړم. او هغوئ به نورو خلقو ته د تهمت، وحشت، لعنت او حقارت مثال وګرځيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18910, 'Jeremiah 44:13', 'Jeremiah', 44, 13, '&nbsp;زۀ به هغوئ ته په مِصر کښې سزا ورکړم لکه څنګه چې مې ورته په يروشلم کښې په جنګ، قحط او وبا سزا ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18911, 'Jeremiah 44:14', 'Jeremiah', 44, 14, '&nbsp;د يهوداه څومره خلق چې دلته مِصر ته پناه اخستو دپاره راغلى دى هغه ټول به دلته هلاک شى. څوک به هم يهوداه ته واپس لاړ نۀ شى. تر دې چې هغوئ به د دوباره هلته د تلو او آبادېدو ډېر خواهش هم کوى. خو په هغوئ کښې به صرف يو څو کسان واپس شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18912, 'Jeremiah 44:15', 'Jeremiah', 44, 15, '&nbsp;د سړو او ښځو يوه لويه ډله چې په هغوئ کښې ځينې کسان په دې موضوع خبر وُو چې د هغوئ ښځو بُتانو ته خوشبويۍ سوزولې او ورسره هغوئ هم څوک چې په شمالى او جنوبى مِصر کښې اوسېدل يرمياه ته يې ووئيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18913, 'Jeremiah 44:16', 'Jeremiah', 44, 16, '&nbsp;”کومه خبره چې تا مونږ ته د مالِک خُدائ په نوم وکړه هغې ته به مونږ غوږ نۀ نيسو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18914, 'Jeremiah 44:17', 'Jeremiah', 44, 17, '&nbsp;مونږ به ضرور په خپلو هغه ټولو خبرو عمل کوُو د کومې خبرې چې مونږه منښته کړې ده، مونږ به آسمانې مَلِکې ته خوشبو سوزوُو او هغې ته به د انګورو د شيرې نذرانې پېش کوُو. مونږ به هغه کارونه کوُو لکه څنګه چې به زمونږ پلار نيکۀ، بادشاهانو، سرکارى کسانو د يهوداه په ښارونو او د يروشلم په کوڅو کښې کول. مونږ سره په هغه وخت کښې خوراک ډېر تېر وو او زندګى مو ښۀ وه او مونږ ته هيڅ قسمه تکليف او مصيبت نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18915, 'Jeremiah 44:18', 'Jeremiah', 44, 18, '&nbsp;خو چې د کوم وخت نه مونږ آسمانې مَلِکې ته د خوشبو سوزول او د څښلو نذرانې پېش کولو رسم بند کړے دے نو مونږ سره هيڅ هم نۀ وُو او په جنګ او قحط باندې مړۀ کېدلوُ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18916, 'Jeremiah 44:19', 'Jeremiah', 44, 19, '&nbsp;نو ښځو خپله خبره جارى وساتله او وې وئيل چې، ”ولې ستاسو دا خيال دے چې ګنې زمونږ خاوندانو ته دا پته نشته چې مونږ آسمانې مَلِکې ته خوشبوئى وسوزوله، د څښلو نذرانه او هغه روټۍ چې پرې مو د هغې شکل جوړ کړے وو پېش کړه؟ نه، بلکل داسې نۀ ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18917, 'Jeremiah 44:20', 'Jeremiah', 44, 20, '&nbsp;نو بيا يرمياه هغه ټولو سړو او ښځو ته وفرمائيل چا چې يو شان جواب ورکړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18918, 'Jeremiah 44:21', 'Jeremiah', 44, 21, '&nbsp;”ولې ستاسو هم دا خيال دے چې ګنې مالِک خُدائ ته دا پته نشته څۀ چې تاسو او ستاسو پلار نيکۀ، ستاسو بادشاهانو او سرکارى کسانو، او ټولو خلقو بُتانو ته د يهوداه په ښارونو او د يروشلم په کوڅو کښې خوشبوئى سوزولې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18919, 'Jeremiah 44:22', 'Jeremiah', 44, 22, '&nbsp;دا ځکه وشُو چې، نور مالِک خُدائ ستاسو د شرارت نه ډک او حرام کارونه نۀ شو برداشت کولے، نو د دې په وجه ستاسو زمکه د لعنت مثال وګرځېده، او په صحرا او کنډرو بدله شوه چې تر ننه پورې هيڅ څوک په کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18920, 'Jeremiah 44:23', 'Jeremiah', 44, 23, '&nbsp;دا مصيبتونه ځکه په تاسو باندې راغلل چې تاسو بُتانو ته خوشبو وسوزوله او د مالِک خُدائ خلاف مو ګناه وکړه. تاسو د هغۀ د حکمونو منلو نه اِنکار وکړو او نۀ مو د هغۀ په لارښودنو، اصُولو او شريعت باندې عمل وکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18921, 'Jeremiah 44:24', 'Jeremiah', 44, 24, '&nbsp;نو بيا يرمياه ټولو ناريناؤ او زناناؤ ته وفرمائيل چې، ”اے د يهوداه خلقو تاسو څوک چې په مِصر کښې اوسېږئ د مالِک خُدائ کلام ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18922, 'Jeremiah 44:25', 'Jeremiah', 44, 25, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تاسو او ستاسو ښځو ووئيل چې، مونږ به ضرور خپلې وعدې پوره کوُو او آسمانې مَلِکې ته به د خوشبو سوزولو او د څښلو نذرانې پېش کوُو. نو تاسو چې څۀ کول نو هغه وکړئ او خپله وعده او منښته هغې ته پوره کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18923, 'Jeremiah 44:26', 'Jeremiah', 44, 26, '&nbsp;خو اوس تاسو ټول د مالِک خُدائ دې پېغام ته غوږ ونيسئ، تاسو د يهوداه ټولو خلقو څوک چې اوس په مِصر کښې اوسېږئ، زۀ په ژوندى مالِک قادر مطلق خُدائ قسم خورم، مالِک خُدائ فرمائى چې، زما نوم به نور هيڅکله په مِصر کښې د يو يهودى په خولۀ وانۀ خستلے شى. په تاسو کښې به يو هم زما نوم د دُعا او د قسم خوړلو دپاره استعمال نۀ کړى، هغه دا چې، په يقين سره مالِک قادر مطلق خُدائ ژوندے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18924, 'Jeremiah 44:27', 'Jeremiah', 44, 27, '&nbsp;زۀ به په تاسو ضرور افتونه نازل کړم، نه چې آبادى. د يهوداه هر يو کس څوک چې اوس په مِصر کښې اوسيږى ټول به جنګ او يا په قحط کښې مړۀ شى ترڅو چې يو هم ژوندے پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18925, 'Jeremiah 44:28', 'Jeremiah', 44, 28, '&nbsp;صرف يو څو کسان به د مرګ نه وتښتى او د مِصر نه به يهوداه ته واپس شى. نو بيا ټول هغه کسان چې مِصر ته راغلى دى نو هغوئ ته به دا پته ولګى چې د چا خبره رښتيا ده، زما او کۀ د هغوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18926, 'Jeremiah 44:29', 'Jeremiah', 44, 29, '&nbsp;مالِک خُدائ فرمائى چې، دا به تاسو دپاره نښه وى چې زۀ په دې ځائ کښې تاسو ته سزا درکړم، نو تاسو به په دې پوهه شئ چې ما ستاسو خلاف صرف خبرې نۀ دى کړې بلکې ضرور به سزا هم درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18927, 'Jeremiah 44:30', 'Jeremiah', 44, 30, '&nbsp;مالِک خُدائ فرمائى چې، لکه څنګه چې ما د يهوداه بادشاه صدقياه د بابل بادشاه نبوکدنضر ته حواله کړو، دغه شان به زۀ د فِرعون حفرع د مِصر بادشاه هم د هغۀ دشمنانو ته حواله کړم څوک چې د دۀ مرګ پسې ګرځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18928, 'Jeremiah 45:1', 'Jeremiah', 45, 1, '&nbsp;يرمياه نبى باروک د نيرياه زوئ ته د يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال چې د يهوداه بادشاه وو پېغام ورکړو د دې نه وروستو کله چې باروک په طومار کښې هغه څۀ وليکل کوم چې ورته يرمياه فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18929, 'Jeremiah 45:2', 'Jeremiah', 45, 2, '&nbsp;”اے باروکه، دا هغه څۀ دى چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يې تاسو ته فرمائى چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18930, 'Jeremiah 45:3', 'Jeremiah', 45, 3, '&nbsp;تا ووئيل چې افسوس دې په ما وى. زۀ د غمونو او تکليفونو د لاندې شوے يم. ولې زما دا دردونه کافى نۀ وُو څۀ؟ مالِک خُدائ زما په غمونو کښې اضافه وکړه. زۀ د اسويلو نه ستړے ستومانه شوے يم او هيڅ قسم آرام راته نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18931, 'Jeremiah 45:4', 'Jeremiah', 45, 4, '&nbsp;باروکه، مالِک خُدائ داسې فرمائى چې، زۀ به دا قوم تباه کړم کوم چې ما آباد کړے دے. او څۀ چې ما کَرلى دى هغه به د بېخ نه راوباسم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18932, 'Jeremiah 45:5', 'Jeremiah', 45, 5, '&nbsp;ولې تۀ د خپل ځان دپاره د دې نه نور هم زيات د خاص سلوک اُميد کوې څۀ؟ داسې مۀ کوه. زۀ به لوئ افت په دې خلقو نازل کړم. خو تۀ چرته هم ځې نو زۀ به تا ته ستا ژوندون درکړم. مالِک خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18933, 'Jeremiah 46:1', 'Jeremiah', 46, 1, '&nbsp;مالِک خُدائ د غېر‌يهوديانو په حقله يرمياه نبى ته پېغام ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18934, 'Jeremiah 46:2', 'Jeremiah', 46, 2, '&nbsp;کوم پېغام چې د مِصر په حقله وو هغه دا وو چې، د يهوداه بادشاه يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال، د کرکميس د جنګ په موقع کله چې فِرعون نِکوه د مِصر بادشاه او د هغۀ فوجيانو د فرات د سيند سره نزدې د بابل بادشاه نبوکدنضر نه شکست وخوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18935, 'Jeremiah 46:3', 'Jeremiah', 46, 3, '&nbsp;”خپل غټ او واړۀ ډالونه تيار کړئ او د جنګ دپاره راوځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18936, 'Jeremiah 46:4', 'Jeremiah', 46, 4, '&nbsp;خپل آسونه زين کړئ او ورباندې سوارۀ شئ. صفونه جوړ کړئ او د جنګ ټوپۍ په سر کړئ. خپلې نېزې تېرې کړئ، او زغره واچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18937, 'Jeremiah 46:5', 'Jeremiah', 46, 5, '&nbsp;خو زۀ څۀ ګورم؟ چې په مِصرى فوجيانو باندې د يرې نه دهشت راغلے دے او هغوئ د يرې نه لګيا دى په شا کيږى، د هغوئ فوجيانو شکست وخوړلو. او په وارخطايۍ سره په مخه تښتى او هغوئ وروستو نۀ ګورى، او د هرې خوا نه په هغوئ باندې يره خوره شوې ده، مالِک خُدائ داسې فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18938, 'Jeremiah 46:6', 'Jeremiah', 46, 6, '&nbsp;تېزه منډه وهونکے هم نۀ شى تښتېدلے، او نه تکړه فوجى تښتېدلے شى. او هغوئ په شمال کښې د فرات د سيند سره، تيندک خورى او راغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18939, 'Jeremiah 46:7', 'Jeremiah', 46, 7, '&nbsp;څوک دے دا چې لکه د نيل درياب په شان موجونه وهى، لکه د هغه سيند په شان چې اوبۀ يې په بره موجونه وهى او ټوله زمکه لاندې کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18940, 'Jeremiah 46:8', 'Jeremiah', 46, 8, '&nbsp;دا د مِصر فوج دے چې د نيل درياب په شان راوچت شوے دے او لافې وهى چې زۀ به راوچت شم او د سېلاب په شان به ټوله زمکه پټه کړم، زۀ به ټول ښارونه تباه کړم او په هغې کښې ټول خلق به هلاک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18941, 'Jeremiah 46:9', 'Jeremiah', 46, 9, '&nbsp;اے آسونو او جنګى ګاډو روان شئ، اے د مِصر تکړه سپاهيانو په دشمن حمله وکړئ، اے د ايتهوپيا، ليبيا، خلقو ډال راواخلئ او د لِديه خلقو څوک چې په غشو ليندو کښې تکړه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18942, 'Jeremiah 46:10', 'Jeremiah', 46, 10, '&nbsp;ځکه چې دا د مالِک خُدائ ربُ الافواج ورځ ده، د انتقام ورځ، ځکه چې هغه به د خپلو دشمنانو نه انتقام واخلى. د هغۀ تُوره به تر هغې خوړل کوى ترڅو پورې چې مړه شوى نۀ وى، او ترڅو چې د هغوئ په وينو تنده ماته نۀ کړى. په نن ورځ به هغوئ مالِک خُدائ ربُ الافواج خُدائ پاک ته په شمال کښې د فرات د سيند سره د قربانۍ په شان پېش کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18943, 'Jeremiah 46:11', 'Jeremiah', 46, 11, '&nbsp;اے د مِصر پېغلې لورې، جِلعاد ته لاړه شه او هلته دارو ولټوه. خو ستاسو رنګارنګ دوائى به تاسو ته شفا درنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18944, 'Jeremiah 46:12', 'Jeremiah', 46, 12, '&nbsp;قومونه به ستاسو د شرم په حقله خبر شى. زمکه به ستاسو دردناکه ژړا ډکه کړى. ستا تکړه فوجيان به په يو بل تيندک وخورى، او په يو ځائ به راپرېوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18945, 'Jeremiah 46:13', 'Jeremiah', 46, 13, '&nbsp;دا هغه خبر دے چې مالِک خُدائ د يرمياه نبى په وسيله د نبوکدنضر يعنې د بابل د بادشاه د راتلو او د هغۀ په مِصر باندې د حملې په حقله ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18946, 'Jeremiah 46:14', 'Jeremiah', 46, 14, '&nbsp;”د مِصر په ښارونو په مجدال، ميمفِس او تحفنحيس کښې به دا اعلان وکړئ چې، د جنګ دپاره تيار شئ، ځکه چې تُوره به ستاسو خوا او شا کښې هر څۀ وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18947, 'Jeremiah 46:15', 'Jeremiah', 46, 15, '&nbsp;ستاسو جنګيالى ولې راغورزېدلى دى؟ هغوئ د مالِک خُدائ مخې ته نۀ شى ټينګېدلے ځکه چې هغه به هغوئ راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18948, 'Jeremiah 46:16', 'Jeremiah', 46, 16, '&nbsp;هغوئ به ټول تيندکونه خورى، او هغوئ به په يو بل راغورزيږى. هغوئ به يو بل ته وائى، پاڅه، راځئ چې خپلو خلقو او خپل مُلکونو ته واپس لاړ شُو، چرته به چې مونږ د ظالم د تُورې نه بچ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18949, 'Jeremiah 46:17', 'Jeremiah', 46, 17, '&nbsp;نو هغوئ به وائى چې د مِصر بادشاه فِرعون خو تش په خولۀ لوئيږى، هغۀ نه اوس خپله موقع خطا شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18950, 'Jeremiah 46:18', 'Jeremiah', 46, 18, '&nbsp;د دُنيا بادشاه د چا نوم چې مالِک خُدائ ربُ الافواج دے فرمائى چې، زما دې په خپل ذات قسم وى چې، يو کس څوک چې د مِصر خلاف راروان دے هغه لکه څنګه چې د تبور غر لوړ دے، او لکه څنګه چې د کرمل غر د سمندر په غاړه لوړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18951, 'Jeremiah 46:19', 'Jeremiah', 46, 19, '&nbsp;اے د مِصر اوسېدونکو، خپل مال حال راواخلئ او د جلاوطنۍ دپاره تيار شئ، ځکه د ميمفِس ښار به تباه او کنډرې شى، او يو کس به هم په کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18952, 'Jeremiah 46:20', 'Jeremiah', 46, 20, '&nbsp;مِصر لکه د يوې ځوانې سخۍ په شان ښائسته دے، خو د شمال د خوا نه د هغۀ خلاف د غوباړى په شان مچ راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18953, 'Jeremiah 46:21', 'Jeremiah', 46, 21, '&nbsp;د مِصر د کرايه فوجيان لکه د کمزورو سخو په شان دى. هغوئ به هم په يو ځائ راوګرځى او په شريکه به وتښتى، هغوئ به په خپل ځائ باندې ونۀ دريږى. ځکه چې په هغوئ د تباهۍ او افت ورځ راروانه ده، دا د هغوئ دپاره د سزا ورکولو ورځ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18954, 'Jeremiah 46:22', 'Jeremiah', 46, 22, '&nbsp;مِصر به لکه د مار په شان کشار وکړى او په وروستو به وتښتى کله چې د دشمن فوج ورباندې حمله وکړى، هغوئ به د دوئ خلاف تبر په لاس راشى او په دوئ به داسې حمله وکړى لکه څنګه چې يو سړے ونې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18955, 'Jeremiah 46:23', 'Jeremiah', 46, 23, '&nbsp;مالِک خُدائ فرمائى چې، هغوئ به د مِصر خلق د ځنګلى ونو په شان ووهى، ځکه چې د هغوئ شمېر د مُولخانو نه هم ډېر بې‌شمېره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18956, 'Jeremiah 46:24', 'Jeremiah', 46, 24, '&nbsp;د مِصر خلق به وشرميږى، او د شمال خلقو ته به حواله کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18957, 'Jeremiah 46:25', 'Jeremiah', 46, 25, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، ”زۀ به امون د مِصر د تيبس معبود او د مِصر نورو معبودانو ته سزا ورکړم. زۀ به د مِصر بادشاهانو او فِرعون ته او هغوئ ټولو ته سزا ورکړم څوک چې په هغۀ يقين کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18958, 'Jeremiah 46:26', 'Jeremiah', 46, 26, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به هغوئ هغه خلقو ته حواله کړم څوک چې دوئ وژل غواړى، نبوکدنضر د بابل بادشاه او د هغۀ آفسرانو ته. خو وروستو به مِصر کښې د وړاندې په شان خلق بيا آباد شى. دا مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18959, 'Jeremiah 46:27', 'Jeremiah', 46, 27, '&nbsp;”اے زما خِدمتګاره يعقوبه مۀ يرېږه، اے اِسرائيله مۀ يرېږه. زۀ به تاسو د هغه لرې مُلک نه دوباره خپلو کورونو ته راولم، چرته چې تاسو جلاوطن شوى يئ. ستا اولاد به زۀ خپلو کورونو ته د جلاوطنۍ نه واپس راولم. يعقوب به دوباره خپل مُلک ته راشى او په امن او سکون سره به ژوند کوى، او تاسو به څوک هم نۀ يروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18960, 'Jeremiah 46:28', 'Jeremiah', 46, 28, '&nbsp;مالِک خُدائ فرمائى چې، اے زما خِدمتګاره يعقوبه مۀ يرېږه، ځکه زۀ تا سره يم. زۀ به په پوره توګه هغه قومونه تباه کړم کومو ته چې تاسو ما جلا وطن کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به ستاسو په اِنصاف سره تنبيه وکړم، زۀ به تاسو بې‌سزا نۀ پرېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18961, 'Jeremiah 47:1', 'Jeremiah', 47, 1, '&nbsp;دا د مالِک خُدائ هغه کلام دے چې د فِرعون د لښکرو په غزه د حملې کولو نه مخکښې، په يرمياه نبى د فلستيانو په حقله نازل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18962, 'Jeremiah 47:2', 'Jeremiah', 47, 2, '&nbsp;”مالِک خُدائ وفرمائيل چې، وګوره، د شمال نه اوبۀ څنګه راوچتيږى، او د سېلاب په شان په زور شور راروانې دى، دا به ټوله زمکه او هر څۀ چې په کښې دى رالاندې کړى، ښارونه او د هغې اوسېدونکى به ډوب کړى، ټول خلق به د مدد دپاره چغې وهى او څومره خلق چې په کښې اوسيږى هغوئ به ژړا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18963, 'Jeremiah 47:3', 'Jeremiah', 47, 3, '&nbsp;هغوئ به د آسونو د سومونو او پښو ټکار واورى، او د دشمن د جنګى ګاډو غرار او د هغوئ د پايو شور به واورى. پلاران به د يرې نه جام شى او د خپلو بې‌وسه ماشومانو د بچ کولو دپاره به شاته نۀ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18964, 'Jeremiah 47:4', 'Jeremiah', 47, 4, '&nbsp;د ټولو فلستيانو د تباهۍ ورځ رارسېدلې ده او ورسره د هغوئ هم څوک چې به د صور او صيدا خلقو سره مدد کوى. مالِک خُدائ په خپله هغه فلستيان تباه کوى، هغوئ څوک چې ژوندى پاتې شوى دى او د کريت د ساحل نه راغلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18965, 'Jeremiah 47:5', 'Jeremiah', 47, 5, '&nbsp;غزه لور به د غم نه خپل سر ګنجے کړى او د اسقلون ښار به وران او خاموشه شى. اے د مېدانى علاقې پاتې شوو خلقو ترڅو پورې به خپل ځان وهئ او ماتم به کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18966, 'Jeremiah 47:6', 'Jeremiah', 47, 6, '&nbsp;تاسو چغې وهئ، اے د مالِک خُدائ تُورې، ترڅو پورې به تۀ زخمى کول کوې؟ خپل کاش ته واپس لاړه شه، او هلته په آرام پرته اوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18967, 'Jeremiah 47:7', 'Jeremiah', 47, 7, '&nbsp;خو دا به څنګه په آرام شى چې ورته مالِک خُدائ حکم کړے دے، کله چې هغۀ ورته په اسقلون او په ساحل د حملې کولو حکم کړے دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18968, 'Jeremiah 48:1', 'Jeremiah', 48, 1, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک د موآب په حقله فرمائى، ”په نبو ښار باندې افسوس، ځکه چې دا ښار به تباه شى. د قِريَتائم بې‌حرمتى به وشى او قبضه به کړے شى. او د مضبوطې قلعه بې‌حرمتى به وشى او ټوټه ټوټه به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18969, 'Jeremiah 48:2', 'Jeremiah', 48, 2, '&nbsp;د نن نه پس به څوک هم د موآب تعريف ونۀ کړى، په حسبون کښې به خلق د هغې د راغورزولو منصوبې جوړوى، هغوئ وائى راځئ چې د موآب نوم او نشان ختم کړُو. اے د مدمين ښاريې، تۀ به هم خاموشه شې، او تاسو به په تُوره مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18970, 'Jeremiah 48:3', 'Jeremiah', 48, 3, '&nbsp;د حورونايم نه د چغو آوازونو ته غوږ شئ، د لوئې تباهۍ درزار او آوازونه اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18971, 'Jeremiah 48:4', 'Jeremiah', 48, 4, '&nbsp;موآب به ټول تباه شى، د هغې واړۀ ماشومان به په تېزه چغې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18972, 'Jeremiah 48:5', 'Jeremiah', 48, 5, '&nbsp;هغوئ لوحيت ته په بره تلو سخته ژړا کوى، او حورونايم ته په ورکوزېدو سره د تباهۍ د درزار او شور په اورېدو هغوئ په چغو چغو ژړا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18973, 'Jeremiah 48:6', 'Jeremiah', 48, 6, '&nbsp;هغوئ وائى چې، منډه کړئ او ځان بچ کړئ او په صحرا کښې د ځنګلى بوټو په شان شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18974, 'Jeremiah 48:7', 'Jeremiah', 48, 7, '&nbsp;دا چې تا اے موآبه په خپلو اعمالو او دولت باندې باور کولو، نو تاسو به هم ګرفتار شئ، او ستا بُت کموس به هم د خپلو اِمامانو او نورو خادِمانو سره جلاوطن کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18975, 'Jeremiah 48:8', 'Jeremiah', 48, 8, '&nbsp;تباه کوونکے دشمن به د هر يو ښار خلاف حمله وکړى، او يو ښار به هم ترې بچ نۀ شى. هره وادى به تباه شى او هر هوار مېدان به تباه شى. ځکه چې مالِک خُدائ دا حکم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18976, 'Jeremiah 48:9', 'Jeremiah', 48, 9, '&nbsp;په موآب باندې مالګه ودوړوه، ځکه چې هغه به په ښوره او صحرا بدل شى، د هغې ښارونه به وران شى، او هيڅ څوک به په کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18977, 'Jeremiah 48:10', 'Jeremiah', 48, 10, '&nbsp;لعنت دې په هغه کسانو وى څوک چې د مالِک خُدائ په کار کښې غفلت کوى، او خپله تُوره د وينو توېدو نه بچ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18978, 'Jeremiah 48:11', 'Jeremiah', 48, 11, '&nbsp;موآب د ځوانۍ نه واخله تر اوسه پورې په امن او سکون سره وخت تېر کړے دے، هغه جلاوطن شوے نۀ دے. لکه څنګه چې مے په خپل لوښى کښې ځائ په ځائ پراتۀ وى، او د يو لوښى نه بل لوښى ته نۀ وى اړولے شوى. نو د هغې ذائقه هم هغه شان ده لکه څنګه چې يې د اول نه وه، او د هغې خوشبو بدله شوې نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18979, 'Jeremiah 48:12', 'Jeremiah', 48, 12, '&nbsp;خو هغه ورځې راروانې دى، مالِک خُدائ فرمائى چې، کله به زۀ خلق ورولېږم چې موآب د لوښى نه رابهر کړى. او هغوئ به هغه د لوښى نه لکه د ميو په شان توئ کړى او لوښى به زره زره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18980, 'Jeremiah 48:13', 'Jeremiah', 48, 13, '&nbsp;نو په آخر کښې به بيا د موآب خلق د کموس بُت نه شرميږى، لکه څنګه چې بنى اِسرائيل په بيت‌ايل کښې په بُت باندې په يقين کولو شرمېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18981, 'Jeremiah 48:14', 'Jeremiah', 48, 14, '&nbsp;نو بيا تاسو څنګه لافې وهلې چې، مونږ په جنګ کښې ډېر تکړه او باتور فوجيان يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18982, 'Jeremiah 48:15', 'Jeremiah', 48, 15, '&nbsp;موآب به تباه شى او د هغۀ ښارونه به قبضه کړے شى. د هغۀ ښائسته زلمى به حلالېدو دپاره بوتلے شى، دا د هغه بادشاه فرمان دے چې د چا نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18983, 'Jeremiah 48:16', 'Jeremiah', 48, 16, '&nbsp;د موآب د ختمېدو اَنجام رانزدې شوے دے، او د هغۀ بربادى زر راتلونکى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18984, 'Jeremiah 48:17', 'Jeremiah', 48, 17, '&nbsp;اے د موآب دوستانو او ګاونډيانو په دۀ باندې ماتم وکړئ، تاسو څومره چې د هغۀ د شُهرت او نوم نه واقف يئ، نو ووايئ چې، افسوس د موآب د شان او شوکت امسا ماته شوه او د هغې ټول طاقت تس نس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18985, 'Jeremiah 48:18', 'Jeremiah', 48, 18, '&nbsp;اے د ديبون اوسېدونکو د خپل شاندار تخت نه راکوز شئ او په خشکه زمکه او خاورو کښېنئ، ځکه هغه چا چې موآب تباه کړو هغه به ديبون هم ټوټه ټوټه کړى. او هغه به ستاسو ټولې قلعه ګانې راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18986, 'Jeremiah 48:19', 'Jeremiah', 48, 19, '&nbsp;اے د عروعير اوسېدونکو د سړک په غاړه ودرېږئ او خلقو ته وګورئ. د هغه نارينه او زناناؤ نه څوک چې تښتى تپوس وکړئ چې څۀ چل وشو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18987, 'Jeremiah 48:20', 'Jeremiah', 48, 20, '&nbsp;هغوئ به په جواب کښې ووائى چې، د ارنون د سيند په غاړه موآب تباه شو او په شرمونو وشرمېدو، په چغو او سورو په هغۀ ماتم او ژړا وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18988, 'Jeremiah 48:21', 'Jeremiah', 48, 21, '&nbsp;د مالِک خُدائ عدالت په دې غريزه مُلکونو لکه حولون، يهض، مفعت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18989, 'Jeremiah 48:22', 'Jeremiah', 48, 22, '&nbsp;ديبون، نبو، بيت‌دبلاتايم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18990, 'Jeremiah 48:23', 'Jeremiah', 48, 23, '&nbsp;قِريَتائم، بيت‌جمول، بيت‌معون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18991, 'Jeremiah 48:24', 'Jeremiah', 48, 24, '&nbsp;قريوت او بُصره او د موآب په ټولو لرې او نزدې ښارونو نازل شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18992, 'Jeremiah 48:25', 'Jeremiah', 48, 25, '&nbsp;مالِک خُدائ دا اعلان وکړو چې، د موآب ښکر مات شو، او د هغۀ طاقت ختم شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18993, 'Jeremiah 48:26', 'Jeremiah', 48, 26, '&nbsp;مالِک خُدائ فرمائى چې، ”په موآب باندې مے وڅښئ او نشه يې کړئ، ځکه چې هغۀ خپل ځان په ما اوچت ګڼلو، پرېږده چې اوس هغه په خپلو اولټو کښې ورغړى، او پرېږده چې هغه د خلقو د خندا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18994, 'Jeremiah 48:27', 'Jeremiah', 48, 27, '&nbsp;اے موآبه، آيا تا به بنى اِسرائيلو پورې خندا نۀ کوله څۀ؟ آيا ستاسو په خيال هغوئ غلۀ وُو، چې کله به تاسو د هغوئ په حقله خبرې کولې نو په مسخره آميزه توګه به مو خپل سرونه خوځول؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18995, 'Jeremiah 48:28', 'Jeremiah', 48, 28, '&nbsp;اے د موآب اوسېدونکو، تاسو خپل ښارونه پرېږدئ او په ګټانو کښې اوسېږئ. لکه د ګوګوشتکو په شان شئ، چې د غارونو په خولۀ کښې خپل ځان له جاله جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18996, 'Jeremiah 48:29', 'Jeremiah', 48, 29, '&nbsp;مونږ د موآب د کبر په حقله واورېدل، ځکه چې د هغۀ بې‌حده کبر او سوچ، د هغۀ کبر او غرور او د هغۀ د زړۀ د خود غرضۍ نه خبر يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18997, 'Jeremiah 48:30', 'Jeremiah', 48, 30, '&nbsp;مالِک خُدائ فرمائى چې، زۀ د هغوئ د غرور نه خبر يم خو دا بې‌مطلبه دے، او د هغوئ عملونه عبث دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18998, 'Jeremiah 48:31', 'Jeremiah', 48, 31, '&nbsp;نو په دې وجه زۀ په موآب ماتم کوم، زۀ د ټولو موآبيانو دپاره ژړا کوم، او زۀ د قير‌حراست د خلقو دپاره ژړا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18999, 'Jeremiah 48:32', 'Jeremiah', 48, 32, '&nbsp;سبماه، زۀ به په تا وير وکړم د دې نه هم زيات چې مې په يعزير کړى وُو، سبماه ستا د انګورو څانګې تر سمندر پورې رسېدلى دى، خو تباه کوونکے ستا په مېوو او انګورو راپرېوتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19000, 'Jeremiah 48:33', 'Jeremiah', 48, 33, '&nbsp;د موآب د زرخېزه پټو او مُلک نه د خندا او خوشحالۍ آوازونه تلى دى، ما د انګورو د لنګرو نه مے جوړول بند کړى دى، هيڅ څوک هم انګور په خوشحالۍ سره نۀ نچوړوى. تر دې چې هلته شور او چغې اورېدلے شى، خو د خوشحالۍ نه بلکې د جنګ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');